-- CodeComprehend Arena schema.
-- Run in the Supabase SQL editor (or `supabase db push`), then run supabase/seed_problems.sql
-- (generated by `npm run gen:seed`) so ratings are computed server-side from trusted problem ratings.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- profiles
create table if not exists public.profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  username      text unique check (username ~ '^[A-Za-z0-9_\-\.]{3,24}$'),
  display_name  text,
  rating        integer not null default 800,
  rated_count   integer not null default 0,
  solved_count  integer not null default 0,
  best_rating   integer not null default 800,
  target_company text,
  last_active   date,
  streak        integer not null default 0,
  created_at    timestamptz not null default now()
);

alter table public.profiles enable row level security;

drop policy if exists "profiles are readable by everyone" on public.profiles;
create policy "profiles are readable by everyone" on public.profiles for select using (true);

-- Users may only edit cosmetic fields. Rating columns are protected by the trigger below.
drop policy if exists "users update own profile" on public.profiles;
create policy "users update own profile" on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id);

create or replace function public.protect_profile_stats() returns trigger
language plpgsql as $$
begin
  if current_setting('cc.trusted', true) is distinct from 'on' then
    new.rating := old.rating;
    new.rated_count := old.rated_count;
    new.solved_count := old.solved_count;
    new.best_rating := old.best_rating;
    new.streak := old.streak;
    new.last_active := old.last_active;
  end if;
  return new;
end $$;

drop trigger if exists protect_profile_stats on public.profiles;
create trigger protect_profile_stats before update on public.profiles
  for each row execute function public.protect_profile_stats();

-- Auto-create a profile on sign-up.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  base text := regexp_replace(coalesce(new.raw_user_meta_data->>'user_name', new.raw_user_meta_data->>'preferred_username', split_part(new.email, '@', 1), 'user'), '[^A-Za-z0-9_]', '', 'g');
  uname text;
begin
  if length(base) < 3 then base := 'user' || base; end if;
  uname := left(base, 18);
  if exists (select 1 from public.profiles where username = uname) then
    uname := left(base, 14) || '_' || substr(md5(new.id::text), 1, 4);
  end if;
  insert into public.profiles (id, username, display_name)
  values (new.id, uname, coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', uname))
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------- problems (trusted ratings)
create table if not exists public.problems (
  id      text primary key,
  level   smallint not null check (level between 1 and 5),
  rating  integer not null,
  title   text not null,
  stages  smallint not null
);
alter table public.problems enable row level security;
drop policy if exists "problems readable" on public.problems;
create policy "problems readable" on public.problems for select using (true);

-- ---------------------------------------------------------------- progress
create table if not exists public.problem_progress (
  user_id      uuid not null references auth.users(id) on delete cascade,
  problem_id   text not null references public.problems(id) on delete cascade,
  stages       jsonb not null default '{}'::jsonb,
  completed    boolean not null default false,
  best_score   real,
  rating_delta integer,
  attempts     integer not null default 0,
  completed_at timestamptz,
  updated_at   timestamptz not null default now(),
  primary key (user_id, problem_id)
);
alter table public.problem_progress enable row level security;
drop policy if exists "own progress read" on public.problem_progress;
create policy "own progress read" on public.problem_progress for select using (auth.uid() = user_id);
drop policy if exists "own progress insert" on public.problem_progress;
create policy "own progress insert" on public.problem_progress for insert with check (auth.uid() = user_id and completed = false and rating_delta is null);
drop policy if exists "own progress update" on public.problem_progress;
create policy "own progress update" on public.problem_progress for update using (auth.uid() = user_id);

-- completion fields can only be written by submit_problem()
create or replace function public.protect_progress() returns trigger
language plpgsql as $$
begin
  if current_setting('cc.trusted', true) is distinct from 'on' then
    new.completed := coalesce(old.completed, false);
    new.best_score := old.best_score;
    new.rating_delta := old.rating_delta;
    new.completed_at := old.completed_at;
    new.attempts := coalesce(old.attempts, 0);
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists protect_progress on public.problem_progress;
create trigger protect_progress before update on public.problem_progress
  for each row execute function public.protect_progress();

-- ---------------------------------------------------------------- attempts log
create table if not exists public.attempts (
  id            bigint generated always as identity primary key,
  user_id       uuid not null references auth.users(id) on delete cascade,
  problem_id    text not null references public.problems(id) on delete cascade,
  score         real not null,
  time_sec      integer,
  mode          text not null default 'practice',
  rating_before integer,
  rating_after  integer,
  created_at    timestamptz not null default now()
);
create index if not exists attempts_user_idx on public.attempts(user_id, created_at desc);
alter table public.attempts enable row level security;
drop policy if exists "own attempts read" on public.attempts;
create policy "own attempts read" on public.attempts for select using (auth.uid() = user_id);

-- ---------------------------------------------------------------- submit RPC (Elo, server-side)
-- Mirrors src/lib/rating.ts updateRating(). Only the first completion of a problem is rated.
create or replace function public.submit_problem(p_problem_id text, p_score real, p_stages jsonb, p_time_sec integer, p_mode text default 'practice')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  prof public.profiles;
  prob public.problems;
  prev public.problem_progress;
  s real := greatest(0, least(1, coalesce(p_score, 0)));
  k integer;
  e double precision;
  new_rating integer;
  already boolean;
  d date := (now() at time zone 'utc')::date;
  new_streak integer;
begin
  if uid is null then raise exception 'not authenticated'; end if;
  select * into prob from public.problems where id = p_problem_id;
  if not found then raise exception 'unknown problem %', p_problem_id; end if;
  select * into prof from public.profiles where id = uid for update;
  select * into prev from public.problem_progress where user_id = uid and problem_id = p_problem_id;
  already := coalesce(prev.completed, false);

  perform set_config('cc.trusted', 'on', true);

  k := case when prof.rated_count < 10 then 48 when prof.rated_count < 30 then 32 else 20 end;
  e := 1.0 / (1.0 + power(10.0, (prob.rating - prof.rating) / 400.0));
  new_rating := case when already then prof.rating else greatest(100, round(prof.rating + k * (s - e))::integer) end;

  new_streak := case
    when prof.last_active = d then prof.streak
    when prof.last_active = d - 1 then prof.streak + 1
    else 1 end;

  update public.profiles set
    rating = new_rating,
    best_rating = greatest(best_rating, new_rating),
    rated_count = rated_count + case when already then 0 else 1 end,
    solved_count = solved_count + case when already then 0 else 1 end,
    last_active = d,
    streak = new_streak
  where id = uid;

  insert into public.problem_progress as pp (user_id, problem_id, stages, completed, best_score, rating_delta, attempts, completed_at)
  values (uid, p_problem_id, coalesce(p_stages, '{}'::jsonb), true, s, new_rating - prof.rating, 1, now())
  on conflict (user_id, problem_id) do update set
    stages = coalesce(p_stages, pp.stages),
    completed = true,
    best_score = greatest(coalesce(pp.best_score, 0), s),
    rating_delta = coalesce(pp.rating_delta, excluded.rating_delta),
    attempts = pp.attempts + 1,
    completed_at = coalesce(pp.completed_at, now());

  insert into public.attempts (user_id, problem_id, score, time_sec, mode, rating_before, rating_after)
  values (uid, p_problem_id, s, p_time_sec, coalesce(p_mode, 'practice'), prof.rating, new_rating);

  return jsonb_build_object('rating', new_rating, 'delta', new_rating - prof.rating, 'alreadyRated', already, 'streak', new_streak);
end $$;

revoke all on function public.submit_problem(text, real, jsonb, integer, text) from public, anon;
grant execute on function public.submit_problem(text, real, jsonb, integer, text) to authenticated;

-- ---------------------------------------------------------------- leaderboard
create or replace view public.leaderboard with (security_invoker = true) as
  select id, username, display_name, rating, best_rating, solved_count, streak, target_company
  from public.profiles
  where rated_count > 0
  order by rating desc;

-- ---------------------------------------------------------------- AI usage (edge function quota)
create table if not exists public.ai_usage (
  user_id uuid not null references auth.users(id) on delete cascade,
  day     date not null,
  count   integer not null default 0,
  primary key (user_id, day)
);
alter table public.ai_usage enable row level security;
drop policy if exists "own ai usage read" on public.ai_usage;
create policy "own ai usage read" on public.ai_usage for select using (auth.uid() = user_id);
